// Build Instagram API request body from Format Messages output
const msg = $input.first().json;
const userId = msg.user_id || $('Filter & Normalize2').item.json.user_id;
const recipient = { id: userId };

let body;

if (msg.type === 'image' && msg.image_url) {
  body = JSON.stringify({
    recipient: recipient,
    message: {
      attachment: {
        type: 'image',
        payload: { url: msg.image_url, is_reusable: true }
      }
    }
  });
} else if (msg.type === 'quick_replies' && msg.options && msg.options.length > 0) {
  const qr = [];
  const maxBtns = Math.min(msg.options.length, 13);
  for (let i = 0; i < maxBtns; i++) {
    qr.push({
      content_type: 'text',
      title: String(msg.options[i]).substring(0, 20),
      payload: (msg.payloads && msg.payloads[i]) ? String(msg.payloads[i]).substring(0, 1000) : 'OPTION_' + i
    });
  }
  body = JSON.stringify({
    recipient: recipient,
    message: {
      text: String(msg.content || 'Elige una opcion:').substring(0, 2000),
      quick_replies: qr
    }
  });
} else {
  const txt = String(msg.content || msg.text || 'Hola!').substring(0, 1000);
  body = JSON.stringify({
    recipient: recipient,
    message: { text: txt }
  });
}

return [{ json: { body: body, user_id: userId } }];

const q = $json.query || {};
if (q['hub.mode'] === 'subscribe' && q['hub.verify_token'] === 'instagram-webhook') {
  return [{ json: { challenge: q['hub.challenge'] } }];
}
return [{ json: { error: 'invalid token' } }];

const body = $json.body || {};
const entry = body.entry?.[0] || {};
const messaging = entry.messaging?.[0] || {};
const message = messaging.message || {};

// 1) Ignore echo events from messages sent by our own page/bot.
if (message.is_echo === true) return [];

// 2) Extra safety: if sender equals business/page id, treat as self event.
const senderId = String(messaging.sender?.id || '').trim();
const pageId = String(entry.id || '').trim();
if (senderId && pageId && senderId === pageId) return [];

// 3) Ignore non-message events (read, delivery, reaction, etc.).
if (!messaging.message) return [];

// Check quick_reply payload (user tapped a quick reply button)
const quickReplyPayload = String(message.quick_reply?.payload || '').trim();

// Check text message
const text = String(message.text || '').trim();

// Use quick_reply payload as message_text if present (with prefix for agent context)
const messageText = quickReplyPayload
  ? 'QR:' + quickReplyPayload
  : text;

if (!messageText) return [];

const referral = messaging.referral || {};
const adRef = String(referral.ref || '').trim();
const adId = String(referral.ad_id || '').trim();
const adSource = String(referral.source || '').trim();
const adTitle = String(referral.ad_title || '').trim();

return [{ json: {
  user_id: senderId || null,
  message_text: messageText,
  ad_ref: adRef,
  ad_id: adId,
  ad_source: adSource,
  ad_title: adTitle,
  session_key: senderId || 'anon'
} }];

