// Build message sequence using tool outputs first, then [IMG:url] fallback
const agentOutput = $input.first().json;
const outputText = agentOutput.output || agentOutput.text || '';
const user_id = $('Filter & Normalize2').item.json.user_id;

const imageUrls = [];
const seen = new Set();

const pushUrl = (value) => {
  if (typeof value !== 'string') return;
  const url = value.trim();
  if (!/^https?:\/\//i.test(url)) return;
  if (seen.has(url)) return;
  seen.add(url);
  imageUrls.push(url);
};

// 1) Deterministic source: tool observations in intermediateSteps
const steps = Array.isArray(agentOutput.intermediateSteps) ? agentOutput.intermediateSteps : [];
for (const step of steps) {
  const observation = step?.observation;
  let data = observation;

  if (typeof observation === 'string') {
    try {
      data = JSON.parse(observation);
    } catch (_) {
      data = null;
    }
  }

  const results = Array.isArray(data?.results) ? data.results : [];
  for (const row of results) {
    pushUrl(row?.image_url);
  }
}

// 2) Fallback source: [IMG:url] markers generated by the LLM
const imgPattern = /\[IMG:(https?:\/\/[^\]\s]+)\]/g;
let match;
while ((match = imgPattern.exec(outputText)) !== null) {
  pushUrl(match[1]);
}

// Clean text: remove all [IMG:url] markers, collapse excess newlines
const cleanText = outputText
  .replace(/\[IMG:https?:\/\/[^\]\s]+\]/g, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

const messages = [];

if (cleanText) {
  messages.push({ type: 'text', content: cleanText.substring(0, 2000) });
}

// Image messages (max 5 to avoid rate limits)
const maxImages = Math.min(imageUrls.length, 5);
for (let i = 0; i < maxImages; i++) {
  messages.push({ type: 'image', image_url: imageUrls[i] });
}

// Quick replies for multi-product (2+ images)
if (maxImages >= 2) {
  const numButtons = Math.min(maxImages, 3);
  const options = [];
  const payloads = [];

  for (let i = 0; i < numButtons; i++) {
    options.push((i + 1) + '\uFE0F\u20E3');
    payloads.push('SELECT_' + i);
  }
  options.push('\uD83D\uDCDE WhatsApp');
  payloads.push('WHATSAPP');

  messages.push({
    type: 'quick_replies',
    content: '\u00BFCu\u00E1l de estos productos te interesa?',
    options,
    payloads
  });
}

if (messages.length === 0) {
  messages.push({ type: 'text', content: outputText.substring(0, 1000) || '\u00A1Hola! \u00BFC\u00F3mo puedo ayudarte?' });
}

return messages.map((m) => ({ json: { ...m, user_id } }));
